var DATA = {"mode": "types", "types": ["Image: boxes, polygons, keypoints", "Text: NER, classification, Q&A", "Audio: transcription, regions", "Video: frame tracking", "Time series: segmentation"]};
function show(k,v){console.log(k+": "+v);}
var m=DATA.mode;
if(m==="config"){
  show("Label config","XML describing the labeling UI");
  show("Example",DATA.ex);
}else if(m==="task"){
  show("Task JSON",JSON.stringify(DATA.task).slice(0,140));
}else if(m==="install"){
  show("Install","pip install label-studio");
  show("Start","label-studio start");
  show("Then","open http://localhost:8080");
}else if(m==="docker"){
  show("Run","docker compose up (official compose file)");
