}else if(m==="ml"){
  show("ML backend","model pre-labels, humans correct");
  show("Loop","annotate -> train -> pre-label -> repeat");
}else if(m==="webhook"){
  show("Webhooks","notify external systems on events");
  show("Events","annotation created, project updated");
}else if(m==="review"){
  show("Review","a second annotator verifies");
  show("Agreement",DATA.agree+"% across annotators");
}else if(m==="types"){
  console.log("Data types:");DATA.types.forEach(function(t){console.log("  "+t);});
}else if(m==="project"){
  show("Project",DATA.name);
  show("Tasks",DATA.n);
}else if(m==="cli"){
  show("CLI",DATA.cmd);
}else if(m==="stats"){
  show("Annotated",DATA.done+" / "+DATA.total);
  show("Progress",Math.round(DATA.done/DATA.total*100)+"%");
  show("Remaining",DATA.total-DATA.done);
}else if(m==="sdk"){
  show("SDK","label-studio-sdk (Python)");
  show("Does","projects, tasks, and annotations as code");
}else if(m==="workflow"){
